//! Junk sweeper for instance folders.
//!
//! Everything removed here is regenerated by Minecraft or by Kaelis on the
//! next launch: logs, crash dumps, loader caches, extracted natives, server
//! resource packs, the name-to-UUID cache, and interrupted-download staging
//! files. Saves, mods, configuration, resource packs, shaders, screenshots,
//! and options are never touched — deleting those would destroy user work,
//! not junk.
use std::path::Path;

/// Upper bound on entries inspected per instance, so a hostile or enormous
/// folder can never stall startup.
const MAX_ENTRIES: u64 = 50_000;

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct JunkReport {
    pub files: u64,
    pub dirs: u64,
    pub bytes: u64,
}

impl JunkReport {
    pub fn is_empty(self) -> bool {
        self.files == 0 && self.dirs == 0
    }

    pub fn summary(self) -> String {
        if self.is_empty() {
            return "No junk to clean.".to_owned();
        }
        let entries = self.files + self.dirs;
        format!(
            "Cleaned {entries} items · {:.1} MiB freed.",
            self.bytes as f64 / (1024.0 * 1024.0)
        )
    }

    fn add(&mut self, other: JunkReport) {
        self.files += other.files;
        self.dirs += other.dirs;
        self.bytes += other.bytes;
    }
}

/// Folders whose contents are disposable. Minecraft, mod loaders, and Java
/// recreate every one of them on the next launch; none holds user work.
const DISPOSABLE_DIRS: [&str; 11] = [
    "logs",
    "crash-reports",
    ".cache",
    ".mixin.out",
    // Loader scratch: remap classpaths, connector caches, and transformed
    // classes. Every one is rebuilt on the next launch.
    ".fabric",
    ".quilt",
    ".connector",
    "debug",
    "temp",
    "natives",
    // Server packs are re-downloaded from the server on the next join, so a
    // stale copy is only disk usage.
    "server-resource-packs",
];

/// Root-level files that only ever hold diagnostics, caches, or OS noise.
const ROOT_JUNK: [&str; 5] = [
    ".DS_Store",
    "Thumbs.db",
    "desktop.ini",
    "launcher_log.txt",
    // Name-to-UUID cache. Minecraft rewrites it from the account database on
    // the next launch, so removing it loses nothing.
    "usercache.json",
];
const ROOT_JUNK_PREFIXES: [&str; 2] = ["hs_err_pid", "replay_pid"];

fn is_root_junk(name: &str) -> bool {
    ROOT_JUNK.contains(&name)
        || ROOT_JUNK_PREFIXES
            .iter()
            .any(|prefix| name.starts_with(prefix))
}

/// Clean one instance root. Missing folders are fine; a symlinked root is
/// refused rather than followed, so a link can never redirect the sweeper into
/// unrelated files.
pub fn clean_instance(root: &Path) -> std::io::Result<JunkReport> {
    let metadata = match std::fs::symlink_metadata(root) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(JunkReport::default());
        }
        Err(error) => return Err(error),
    };
    if !metadata.is_dir() || metadata.file_type().is_symlink() {
        return Ok(JunkReport::default());
    }
    let mut report = JunkReport::default();
    let mut inspected = 0_u64;
    for name in DISPOSABLE_DIRS {
        let directory = root.join(name);
        let Ok(entries) = std::fs::read_dir(&directory) else {
            continue;
        };
        for entry in entries.flatten() {
            inspected += 1;
            if inspected > MAX_ENTRIES {
                return Ok(report);
            }
            if let Some(removed) = remove_entry(&entry) {
                report.add(removed);
            }
        }
    }
    // Staging files are created next to their destination, so they can appear
    // in the instance root and in every content folder. The instance root also
    // collects JVM crash dumps and OS metadata files.
    for name in ["", "mods", "resourcepacks", "shaderpacks"] {
        let directory = if name.is_empty() {
            root.to_path_buf()
        } else {
            root.join(name)
        };
        let Ok(entries) = std::fs::read_dir(&directory) else {
            continue;
        };
        for entry in entries.flatten() {
            inspected += 1;
            if inspected > MAX_ENTRIES {
                return Ok(report);
            }
            let file_name = entry.file_name().to_string_lossy().to_string();
            let junk = is_staging_name(&file_name) || (name.is_empty() && is_root_junk(&file_name));
            if junk && let Some(removed) = remove_entry(&entry) {
                report.add(removed);
            }
        }
    }
    Ok(report)
}

/// Clean every instance root below `instances_dir`, returning the total.
/// A missing directory is a no-op, not an error.
pub fn clean_instances(instances_dir: &Path) -> std::io::Result<JunkReport> {
    let mut total = JunkReport::default();
    let entries = match std::fs::read_dir(instances_dir) {
        Ok(entries) => entries,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(total),
        Err(error) => return Err(error),
    };
    for entry in entries.flatten() {
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        // Instance records are files next to the folders; skip them without a
        // stat call per entry.
        if !file_type.is_dir() || file_type.is_symlink() {
            continue;
        }
        total.add(clean_instance(&entry.path())?);
    }
    Ok(total)
}

/// `.<anything>part`, `.<anything>tmp`, and Kaelis' own staging prefixes.
fn is_staging_name(name: &str) -> bool {
    if name.starts_with(".kaelis-") {
        return true;
    }
    if !name.starts_with('.') {
        return false;
    }
    name.ends_with(".part") || name.ends_with(".tmp") || name.ends_with(".download")
}

fn remove_entry(entry: &std::fs::DirEntry) -> Option<JunkReport> {
    // `DirEntry::metadata` does not follow symlinks and reuses what the
    // directory read already knows, so the walk below makes one stat per entry
    // instead of resolving the same path twice through `symlink_metadata`.
    let metadata = entry.metadata().ok()?;
    let file_type = metadata.file_type();
    let path = entry.path();
    if file_type.is_symlink() {
        return remove_file(&path).map(|()| JunkReport {
            files: 1,
            dirs: 0,
            bytes: 0,
        });
    }
    if file_type.is_dir() {
        // Count while deleting. Measuring the tree first and then deleting it
        // walked every disposable file twice, which is the larger half of a
        // clean on a big log or cache folder.
        let mut report = JunkReport {
            dirs: 1,
            ..JunkReport::default()
        };
        if remove_contents(&path, &mut report).is_ok() && std::fs::remove_dir(&path).is_ok() {
            return Some(report);
        }
        return None;
    }
    if !file_type.is_file() {
        return None;
    }
    let bytes = metadata.len();
    remove_file(&path).map(|()| JunkReport {
        files: 1,
        dirs: 0,
        bytes,
    })
}

/// Delete everything below `directory`, adding each removed file and byte to
/// `report`. Symlinks are unlinked, never traversed.
fn remove_contents(directory: &Path, report: &mut JunkReport) -> std::io::Result<()> {
    for entry in std::fs::read_dir(directory)? {
        let Ok(entry) = entry else {
            continue;
        };
        let Ok(metadata) = entry.metadata() else {
            continue;
        };
        let file_type = metadata.file_type();
        let path = entry.path();
        if file_type.is_symlink() {
            if remove_file(&path).is_some() {
                report.files += 1;
            }
        } else if file_type.is_dir() {
            remove_contents(&path, report)?;
            std::fs::remove_dir(&path)?;
        } else if file_type.is_file() {
            let bytes = metadata.len();
            if remove_file(&path).is_some() {
                report.files += 1;
                report.bytes = report.bytes.saturating_add(bytes);
            }
        }
    }
    Ok(())
}

/// Read-only files are common in extracted game data, and `remove_dir_all`
/// clears that attribute before retrying. Do the same so a direct unlink never
/// leaves junk behind that the standard recursive delete would have removed.
// The clippy lint targets Unix, where `set_readonly(false)` widens the mode.
// This branch only compiles on Windows, where it clears FILE_ATTRIBUTE_READONLY
// and is exactly what the standard recursive delete does.
#[cfg(windows)]
#[allow(clippy::permissions_set_readonly_false)]
fn remove_file(path: &Path) -> Option<()> {
    match std::fs::remove_file(path) {
        Ok(()) => Some(()),
        // On Windows an unlink fails while the read-only attribute is set, and
        // `remove_dir_all` clears it before retrying. Unix unlink permission
        // comes from the folder, so a read-only file needs no second attempt
        // (and clearing its mode there would widen access instead).
        Err(_) => {
            let permissions = std::fs::metadata(path).ok()?.permissions();
            if permissions.readonly() {
                let mut writable = permissions;
                writable.set_readonly(false);
                std::fs::set_permissions(path, writable).ok()?;
            }
            std::fs::remove_file(path).ok()
        }
    }
}

/// Unix unlink permission comes from the folder, so a read-only file needs no
/// second attempt (and clearing its mode would widen access instead).
#[cfg(not(windows))]
fn remove_file(path: &Path) -> Option<()> {
    std::fs::remove_file(path).ok()
}

#[cfg(test)]
mod tests {
    use super::{JunkReport, clean_instance, clean_instances};
    use std::path::{Path, PathBuf};

    fn scratch(label: &str) -> PathBuf {
        let path = std::env::temp_dir().join(format!(
            "kaelis-junk-{label}-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&path).unwrap();
        path
    }

    fn write(path: &Path, bytes: &[u8]) {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).unwrap();
        }
        std::fs::write(path, bytes).unwrap();
    }

    #[test]
    fn removes_logs_crashes_and_staging_but_keeps_user_data() {
        let root = scratch("instance");
        write(&root.join("logs/2026-10-20-1.log"), b"log line");
        write(&root.join("logs/latest.log"), b"latest");
        write(&root.join("crash-reports/crash-2026-10-20.txt"), b"boom");
        write(&root.join("mods/sodium.jar"), b"jar");
        write(&root.join("mods/.kaelis-import-1-2.part"), b"partial");
        write(
            &root.join("resourcepacks/.kaelis-import-1-3.part"),
            b"partial",
        );
        write(&root.join(".kaelis-mrpack-1"), b"stage");
        write(&root.join(".cache/iris/pipeline.bin"), b"cache");
        write(&root.join(".mixin.out/audit.txt"), b"mixin");
        write(&root.join(".fabric/remapClasspath.txt"), b"classes");
        write(&root.join(".quilt/remapClasspath.txt"), b"classes");
        write(&root.join("debug/profiler.txt"), b"debug");
        write(&root.join("hs_err_pid4242.log"), b"jvm crash");
        write(&root.join("usercache.json"), b"[]");
        write(&root.join("server-resource-packs/legacy_pack.zip"), b"pack");
        write(&root.join("Thumbs.db"), b"noise");
        write(&root.join("saves/world/level.dat"), b"level");
        write(&root.join("options.txt"), b"options");
        write(&root.join("config/sodium.json"), b"{}");
        write(&root.join("defaultconfigs/sodium.json"), b"{}");

        let report = clean_instance(&root).expect("clean");
        // Two logs, one crash report, two staging files, one root stage, one
        // cache file, one mixin audit, two loader scratch files, one debug
        // file, one JVM dump, one UUID cache, one server pack, one OS
        // metadata file.
        assert_eq!(report.files, 15);
        assert!(report.bytes > 0);
        assert!(!root.join("logs/2026-10-20-1.log").exists());
        assert!(!root.join("crash-reports/crash-2026-10-20.txt").exists());
        assert!(!root.join("mods/.kaelis-import-1-2.part").exists());
        // The three things that actually matter survive untouched.
        assert!(root.join("mods/sodium.jar").is_file());
        assert!(root.join("saves/world/level.dat").is_file());
        assert!(root.join("options.txt").is_file());
        assert!(root.join("config/sodium.json").is_file());
        assert!(root.join("defaultconfigs/sodium.json").is_file());
        assert!(!root.join(".cache/iris/pipeline.bin").exists());
        assert!(!root.join(".mixin.out/audit.txt").exists());
        assert!(!root.join(".fabric/remapClasspath.txt").exists());
        assert!(!root.join(".quilt/remapClasspath.txt").exists());
        assert!(!root.join("debug/profiler.txt").exists());
        assert!(!root.join("hs_err_pid4242.log").exists());
        assert!(!root.join("usercache.json").exists());
        assert!(!root.join("server-resource-packs/legacy_pack.zip").exists());
        assert!(!root.join("Thumbs.db").exists());
        assert!(root.join("logs").is_dir(), "the folder itself is kept");
        let _ = std::fs::remove_dir_all(root);
    }

    #[cfg(windows)]
    #[test]
    fn removes_a_read_only_log_instead_of_leaving_it_behind() {
        let root = scratch("readonly");
        let log = root.join("logs/latest.log");
        write(&log, b"locked");
        let mut permissions = std::fs::metadata(&log).unwrap().permissions();
        permissions.set_readonly(true);
        std::fs::set_permissions(&log, permissions).unwrap();
        let report = clean_instance(&root).expect("clean");
        assert_eq!(report.files, 1);
        assert!(!log.exists());
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn ignores_a_missing_or_foreign_root() {
        let root = scratch("missing");
        let missing = root.join("does-not-exist");
        assert_eq!(clean_instance(&missing).unwrap(), JunkReport::default());

        let file = root.join("not-a-folder");
        write(&file, b"x");
        assert_eq!(clean_instance(&file).unwrap(), JunkReport::default());
        assert!(file.is_file());
        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn cleans_every_instance_folder_in_one_pass() {
        let root = scratch("all");
        let instances = root.join("instances");
        write(&instances.join("a/logs/latest.log"), b"a");
        write(&instances.join("a/saves/world/level.dat"), b"keep");
        write(&instances.join("b/crash-reports/crash.txt"), b"b");
        write(&instances.join("a.json"), b"{}");

        let report = clean_instances(&instances).unwrap();
        assert_eq!(report.files, 2);
        assert!(instances.join("a/saves/world/level.dat").is_file());
        assert!(instances.join("a.json").is_file());
        assert_eq!(
            clean_instances(&root.join("absent")).unwrap(),
            JunkReport::default()
        );
        let _ = std::fs::remove_dir_all(root);
    }
}
